files.gc.bzl:
def _go_config_impl(ctx):
    out = ctx.actions.declare_file(ctx.label.name + ".txt")
    ctx.actions.write(out, "debug={}\nforce_pic={}\nstamp={}\nstrip={}\n".format(ctx.attr.debug, ctx.attr.force_pic, ctx.attr.stamp, ctx.attr.strip))
    return [DefaultInfo(files = depset([out]))]

go_config = rule(implementation = _go_config_impl, attrs = {
    "debug": attr.bool(),
    "force_pic": attr.bool(),
    "stamp": attr.bool(),
    "strip": attr.bool(),
})

files.BUILD.bazel:
load(":gc.bzl", "go_config")

go_config(
    name = "go_config",
    debug = select({
        "//go/private:is_compilation_mode_dbg": True,
        "//conditions:default": False,
    }),
    force_pic = select({
        "//go/private:force_pic": True,
        "//conditions:default": False,
    }),
    stamp = select({
        "//go/private:stamp": True,
        "//conditions:default": False,
    }),
    strip = select({
        "//go/private:is_strip_always": True,
        "//go/private:is_strip_sometimes_fastbuild": True,
        "//conditions:default": False,
    }),
    visibility = ["//visibility:public"],
)

